package com.chilicraft.quest;
import org.bukkit.configuration.*; import org.bukkit.configuration.file.YamlConfiguration; import java.io.File; import java.util.*;
final class QuestContentLoader {
    private final File file; private final java.util.logging.Logger log; private List<ChapterDefinition> chapters=List.of(); private Map<String,List<QuestDefinition>> index=Map.of();
    QuestContentLoader(File file, java.util.logging.Logger log){this.file=file;this.log=log;}
    boolean reload(){try{YamlConfiguration c=YamlConfiguration.loadConfiguration(file); ConfigurationSection root=c.getConfigurationSection("chapters"); if(root==null) throw new IllegalArgumentException("缺少 chapters"); List<ChapterDefinition> out=new ArrayList<>(); Set<String> ids=new HashSet<>(); for(String cid:root.getKeys(false)){if(!ids.add(cid))throw new IllegalArgumentException("章节重复"); ConfigurationSection cs=root.getConfigurationSection(cid); List<QuestDefinition> qs=new ArrayList<>(); Set<String> qids=new HashSet<>(); for(Map<?,?> raw:cs.getMapList("tasks")){String id=String.valueOf(raw.get("id")); if(!qids.add(id))throw new IllegalArgumentException("任务重复"); String base="chapters."+cid+".tasks"; int n=qs.size(); String p=base+"."+n; String event=c.getString(p+".target.event"); int amount=c.getInt(p+".target.amount",0); int souls=c.getInt(p+".reward.souls",-1); if(event==null||event.isBlank()||amount<=0||souls<0)throw new IllegalArgumentException("任务配置非法: "+id); qs.add(new QuestDefinition(cid,id,c.getString(p+".title",id),c.getString(p+".description",""),new QuestTarget(event,amount,c.getString(p+".target.target"),c.isInt(p+".target.value")?c.getInt(p+".target.value"):null),new QuestReward(souls)));} if(qs.isEmpty())throw new IllegalArgumentException("章节无任务: "+cid); out.add(new ChapterDefinition(cid,cs.getString("title",cid),cs.getInt("order",0),List.copyOf(qs)));} out.sort(Comparator.comparingInt(ChapterDefinition::order)); Map<String,List<QuestDefinition>> ix=new HashMap<>(); out.forEach(ch->ch.quests().forEach(q->ix.computeIfAbsent(q.target().event(),k->new ArrayList<>()).add(q))); chapters=List.copyOf(out); index=ix.entrySet().stream().collect(java.util.stream.Collectors.toUnmodifiableMap(Map.Entry::getKey,e->List.copyOf(e.getValue()))); return true;}catch(Exception e){log.warning("任务内容加载失败，保留旧快照："+e.getMessage());return !chapters.isEmpty();}}
    List<ChapterDefinition> chapters(){return chapters;} Map<String,List<QuestDefinition>> index(){return index;}
}
